import{c as s,U as n,j as e,m as i}from"./chunks/framework.DQFmIr4R.js";const b=JSON.parse('{"title":"载荷格式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specification/payload.md","filePath":"zh/specification/payload.md","lastUpdated":1782214112000}'),t={name:"zh/specification/payload.md"};function l(p,a,r,d,c,o){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="载荷格式" tabindex="-1">载荷格式 <a class="header-anchor" href="#载荷格式" aria-label="Permalink to “载荷格式”">​</a></h1><p>载荷分为 <strong>A区</strong>（文件元数据+内容）和 <strong>B区</strong>（Manifest+自定义数据），两区完全独立。</p><h2 id="a区-b区分离设计" tabindex="-1">A区/B区分离设计 <a class="header-anchor" href="#a区-b区分离设计" aria-label="Permalink to “A区/B区分离设计”">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>内容</th><th>加密时</th><th>未加密时</th></tr></thead><tbody><tr><td>A区</td><td>文件数量 + 路径条目 + 文件内容</td><td>AES-256 加密</td><td>压缩 + S-Box</td></tr><tr><td>B区</td><td>Manifest + CustomData</td><td>压缩 + S-Box（明文）</td><td>压缩 + S-Box（明文）</td></tr></tbody></table><blockquote><p><strong>注意</strong>：B区仅在 <code>HasManifest=1</code> 或 <code>HasCustom=1</code> 时存在。如果两者均为 0，文件在 A区数据结束后即终止。</p></blockquote><hr><h2 id="文件布局" tabindex="-1">文件布局 <a class="header-anchor" href="#文件布局" aria-label="Permalink to “文件布局”">​</a></h2><h3 id="未加密模式-encrypted-0" tabindex="-1">未加密模式（Encrypted = 0） <a class="header-anchor" href="#未加密模式-encrypted-0" aria-label="Permalink to “未加密模式（Encrypted = 0）”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ TTP 头部 (26 字节)                               │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ A区长度 (4 bytes, uint32 LE)                     │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ [A区] 压缩 + S-Box 后的数据                      │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ [B区] 压缩 + S-Box 后的数据（可选）              │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="加密模式-encrypted-1" tabindex="-1">加密模式（Encrypted = 1） <a class="header-anchor" href="#加密模式-encrypted-1" aria-label="Permalink to “加密模式（Encrypted = 1）”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ TTP 头部 (26 字节)                               │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ A区长度 (4 bytes, uint32 LE)                     │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ [加密区] AES-256 加密的 A区数据                  │</span></span>
<span class="line"><span>│   内部 = Salt(16B) + IV(12B) + A区密文           │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ [B区] 压缩 + S-Box 后的数据（可选）              │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="a区明文内容" tabindex="-1">A区明文内容 <a class="header-anchor" href="#a区明文内容" aria-label="Permalink to “A区明文内容”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>文件数量 (4 bytes, uint32 LE)</span></span>
<span class="line"><span>├── 文件条目 1:</span></span>
<span class="line"><span>│   - 路径长度 (2 bytes, uint16 LE)</span></span>
<span class="line"><span>│   - 路径 (UTF-8, 如 &quot;folder/sub/file.txt&quot;)</span></span>
<span class="line"><span>│   - 内容长度 (8 bytes, uint64 LE)</span></span>
<span class="line"><span>│   - 内容 (原始字节)</span></span>
<span class="line"><span>├── 文件条目 2:</span></span>
<span class="line"><span>│   ...</span></span></code></pre></div><ul><li>文件数量最大约 42.9 亿（uint32）</li><li>路径最长 65535 字节（uint16）</li><li>文件内容最大 2^64 字节（uint64）</li></ul><hr><h2 id="b区明文内容" tabindex="-1">B区明文内容 <a class="header-anchor" href="#b区明文内容" aria-label="Permalink to “B区明文内容”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[HasManifest = 1 时]</span></span>
<span class="line"><span>  Manifest 长度 (4 bytes, uint32 LE)</span></span>
<span class="line"><span>  Manifest 文本 (UTF-8 JSON)</span></span>
<span class="line"><span>[HasCustom = 1 时]</span></span>
<span class="line"><span>  自定义数据长度 (8 bytes, uint64 LE)</span></span>
<span class="line"><span>  自定义数据 (原始字节)</span></span></code></pre></div><blockquote><p><strong>Manifest 语义</strong>：Manifest 仅用于存储应用自定义信息（如版本号、作者、项目名）。文件目录结构完全由二进制路径条目还原，<strong>不再依赖 Manifest</strong>。</p></blockquote><hr><h2 id="加密参数-加密区内部前置" tabindex="-1">加密参数（加密区内部前置） <a class="header-anchor" href="#加密参数-加密区内部前置" aria-label="Permalink to “加密参数（加密区内部前置）”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Salt (16 bytes)  — PBKDF2 盐值</span></span>
<span class="line"><span>IV   (12 bytes)  — AES-256-GCM 初始向量</span></span>
<span class="line"><span>Ciphertext       — AES-256-GCM 加密的 A区数据（含 Auth Tag）</span></span></code></pre></div><p>密钥派生：PBKDF2-HMAC-SHA256，100000 次迭代，从 password + Salt 派生 32 字节密钥。</p><hr><h2 id="路径规范" tabindex="-1">路径规范 <a class="header-anchor" href="#路径规范" aria-label="Permalink to “路径规范”">​</a></h2><ul><li>路径分隔符<strong>必须使用 <code>/</code></strong>（无论打包系统）</li><li>解包时由解包器转换为当前系统的路径分隔符</li><li>路径长度单位为<strong>字节数</strong>（非字符数）</li><li>不允许包含 <code>\\0</code> 字节</li><li>路径最长 65535 字节（uint16）</li></ul><hr><h2 id="边界情况" tabindex="-1">边界情况 <a class="header-anchor" href="#边界情况" aria-label="Permalink to “边界情况”">​</a></h2><ul><li><strong>空目录</strong>：<code>collect_files()</code> 静默跳过空目录，不保留在载荷中</li><li><strong>空载荷</strong>：允许打包空目录（文件数量 = 0）</li><li><strong>路径安全</strong>：解包器必须检测路径穿越攻击（<code>../</code>）</li></ul>`,29)])])}const g=s(t,[["render",l]]);export{b as __pageData,g as default};
